$D="$env:TEMP\DataT";$Z="$env:TEMP\DataT.zip";Remove-Item $D,$Z -Recurse -Force -ErrorAction SilentlyContinue;New-Item $D -ItemType Directory -Force|Out-Null;$C=@{Pictures=".jpg",".jpeg",".png",".gif",".webp",".bmp",".svg";Videos=".mp4",".mkv",".mov",".avi",".wmv",".webm";Audio=".mp3",".wav",".flac",".m4a",".ogg";Documents=".doc",".docx",".xls",".xlsx",".ppt",".pptx";Text=".txt",".csv",".json",".xml",".log",".md";PDF=".pdf";Programs=".exe",".msi",".bat",".cmd",".ps1",".py",".js";Archives=".zip",".rar",".7z",".tar",".gz"};"Desktop","Downloads","Documents","Pictures","Videos","Music"|%{$S="$env:USERPROFILE\$_";if(Test-Path $S){Get-ChildItem $S -Recurse -File -ErrorAction SilentlyContinue|%{$E=$_.Extension.ToLower();$T=($C.Keys|?{$C[$_] -contains $E}|select -First 1);if(!$T){$T="Other"};$P="$D\$T";New-Item $P -ItemType Directory -Force|Out-Null;$N=$_.Name;$I=1;while(Test-Path "$P\$N"){$N="$($_.BaseName)_$I$($_.Extension)";$I++};Copy-Item $_.FullName "$P\$N" -Force -ErrorAction SilentlyContinue}}};Compress-Archive "$D\*" $Z -Force;Remove-Item $D -Recurse -Force;Write-Host "Created: $Z"